class Product {
    String name;
    double price;
    String category;
    boolean inStock;

    // Most minimal — name and price only
    Product(String name, double price) {
        this(name, price, "General");
    }
    // Name, price, category — inStock defaults to true
    Product(String name, double price, String category) {
        this(name, price, category, true);
    }
    // Full constructor — all others delegate here
    Product(String name, double price, String category, boolean inStock) {
        this.name = name;
        this.price = price;
        this.category = category;
        this.inStock = inStock;
    }
}
// Usage:
Product p1 = new Product("Book", 299.0);
Product p2 = new Product("Pen", 15.0, "Stationery");
Product p3 = new Product("Laptop", 75000.0, "Electronics", false);

